typedef unsigned int u_int;

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const stringx &);
};

template<class T> class my_allocator;
class malloc_alloc;

template<class T, class Alloc = my_allocator<T> >
class vector
{
public:
  typedef T *iterator;
  T *start;
  T *finish;
  T *end_of_storage;
  iterator begin() { return start; }
  iterator end() { return finish; }
  void _M_insert_aux(iterator, const T &);
  void push_back(const T &x)
  {
    if (finish != end_of_storage)
    {
      if (finish) *finish = x;
      ++finish;
    }
    else
      _M_insert_aux(finish, x);
  }
};

template<class Iterator, class T>
Iterator find(Iterator, Iterator, const T &);

class entity;
class entity_link_ifc
{
  char pad[8];
  entity *parent;
public:
  entity *get_parent() const { return parent; }
};

class entity
{
  char pad0[0x68];
  entity_link_ifc *my_link_ifc;
  char pad1[0x12c];
  u_int ext_flags;
public:
  void set_ext_flag(u_int f, bool set)
  {
    if (set) ext_flags |= f;
    else ext_flags &= ~f;
  }
  bool has_parent() const { return my_link_ifc->get_parent() != 0; }
  entity_link_ifc *link_ifc() const { return my_link_ifc; }
};

enum { EFLAG_EXT_MEMBER = 0x800 };
typedef vector<entity *> pentity_vector;

class conglomerate : public entity
{
  pentity_vector members;
  vector<stringx, malloc_alloc> names;
  vector<char> parents;
public:
  void add_member(entity *, const stringx &);
};

void conglomerate::add_member( entity* ent, const stringx& nodename )
{
  members.push_back( ent );
  names.push_back( nodename );

  ent->set_ext_flag(EFLAG_EXT_MEMBER, true);

  char pidx = -1;
  pentity_vector::iterator ei;
  ei = find( members.begin(), members.end(), ent->link_ifc()->get_parent() );
  if ( ei != members.end() )
    pidx = ei - members.begin();
  parents.push_back( pidx );
}
